window.ScripturaLexicons.DGP.entriesHtml += "<article id=\"entry-dgp-42501\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φθίσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 295 na letra φ · nº geral 42501</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 destruição; extinção 2 declínio; ocaso (de astro) 3 emagrecimento; consunção; definhamento 4 Medic. tísica; tuberculose. 〈φθίω〉</p></section></article>\n<article id=\"entry-dgp-42502\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φθῖτο</h1><div class=\"entry-meta\"><span>DGP · ordem 296 na letra φ · nº geral 42502</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. opt aor.2 méd. de φθίω.</p></section></article>\n<article id=\"entry-dgp-42503\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φθιτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 297 na letra φ · nº geral 42503</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 consumido; destruído; morto 2 exposto a perecer; sujeito a ser destruído. 〈φθίω〉</p></section></article>\n<article id=\"entry-dgp-42504\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φθίω</h1><div class=\"entry-meta\"><span>DGP · ordem 298 na letra φ · nº geral 42504</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. φθίσω, aor. ἔφθισα, perf. ἔφθικα; pas. aor. ἔφθιθην, aor.1 hom. ἐφθίθην, perf. ἔφθιμαι) 1 intr. (pres. e impf.) perecer; enfraquecer-se; consumir-se; murchar: ἀχέων φρένας ἔφθιεν hom. consumia o coração de dor 2 (fut. e aor.) fazer perecer lentamente; consumir; destruir pouco a pouco ♦ méd. pas. (fut. φθίσομαι, perf. ἔφθιμαι, m.-q.-perf. ἐφθίμην com valor de aor.2, aor. ἐφθίμην, subj. φθίωμαι, ép. φθίομαι, φθίεται, φθιόμεσθα, opt. φθίμην, φθῖο, φθῖτο, inf. φθίσθαι, part. φθίμενος) 3 definhar; consumir-se: φθ. κακὸν οἶτον hom. perecer por uma morte funesta, φθ. νόσοις sóf. morrer consumido por doenças, οἱ φθίμενοι os mortos.</p></section></article>\n<article id=\"entry-dgp-42505\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φθιώτης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 299 na letra φ · nº geral 42505</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) da Ftiótida. 〈Φθία〉</p></section></article>\n<article id=\"entry-dgp-42506\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φθιῶτις, ιδος</h1><div class=\"entry-meta\"><span>DGP · ordem 300 na letra φ · nº geral 42506</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) 1 da Ftiótida ♦ ἡ Φθιῶτις 2 Ftiótida, região da Tessália.</p></section></article>\n<article id=\"entry-dgp-42507\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φθογγή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 301 na letra φ · nº geral 42507</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 voz (humana) 2 voz; grito; canto (de animais). 〈φθέγγομαι〉</p></section></article>\n<article id=\"entry-dgp-42508\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φθόγγος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 302 na letra φ · nº geral 42508</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ruído 2 som; grito; canto (de animais) 3 som articulado; voz; palavra; linguagem. 〈φθέγγομαι〉</p></section></article>\n<article id=\"entry-dgp-42509\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φθόη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 303 na letra φ · nº geral 42509</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">esgotamento; consunção; definhamento. 〈φθίω〉</p></section></article>\n<article id=\"entry-dgp-42510\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φθόϊς,</h1><div class=\"entry-meta\"><span>DGP · ordem 304 na letra φ · nº geral 42510</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">contr. át. φθοῖς nom. e ac. pl. jôn. φθόεις, contr. φθοῖς (ὁ) 1 torta (redonda, de farinha, queijo e mel) 2 Medic. pastilha usada em fumegação 3 um tipo de taça.</p></section></article>\n<article id=\"entry-dgp-42511\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φθονερός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 305 na letra φ · nº geral 42511</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 invejoso; ciumento 2 que provoca a inveja ou rancor. 〈φθόνος〉</p></section></article>\n<article id=\"entry-dgp-42512\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φθονέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 306 na letra φ · nº geral 42512</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. φθονήσω, aor. ἐφθόνησα, perf. πεφθόνεκα) 1 alimentar rancor; ter inveja de; ser invejoso de alguém, dat., ou de algo, gen. ou ἐπί e dat.; com e dat.: invejar; ver com maus olhos algo, gen., de alguém, dat.; ter inveja de que, or. conj. (ὅτι): μή μοι φθονήσῃς τοῦ μαθήματος plat. não me invejes por meu aprendizado 2 recusar algo, gen. ou ac., por inveja ou por maldade, a alguém, dat.: οὔτε τοι ἡμιόνων φθονέω hom. não te recuso mulas 3 recusar-se a; esquivar-se de, inf. ou part.: οὐκ ἂν φθονέοιμι ἀγορεῦσαι hom. não me recusaria a narrar, μηδὲ μοι φθόνει λέγων ésql. e não te recuses a dizer-me 4 opor-se a alguém, dat., de, inf., ou or. inf.: τῇ δ᾽ οὐκ ἂν φθονέοιμι ποδῶν ἅψασθαι ἐμεῖο hom. não me oporia a que ela [a anciã] tocasse em meus pés, οὔτε τινὰ φθονέω δόμεναι hom. não me oponho a que alguém dê ♦ pas. 5 ser invejado; tornar-se odioso por causa de algo, gen. ou ἐπί e dat. 〈φθόνος〉</p></section></article>\n<article id=\"entry-dgp-42513\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φθόνησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 307 na letra φ · nº geral 42513</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">φθόνος. 〈φθονέω〉</p></section></article>\n<article id=\"entry-dgp-42514\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φθονητικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 308 na letra φ · nº geral 42514</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">invejoso. 〈φθονέω〉</p></section></article>\n<article id=\"entry-dgp-42515\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φθονητικῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 309 na letra φ · nº geral 42515</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com um temperamento invejoso; com inveja.</p></section></article>\n<article id=\"entry-dgp-42516\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φθόνος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 310 na letra φ · nº geral 42516</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 espírito depreciativo; depreciação; maldade 2 inveja; ciúme de alguém, gen., ἐπί e dat., εἰς ou πρός e ac.: φθόνον ἔχειν e φθόνῳ χρῆσθαι plat. ser alvo de inveja, φθόνῳ her., κατὰ φθόνον ésql., ξὺν φθόνῳ eur., διὰ φθόνου N.T. por inveja 3 pl. sentimentos, sinais de inveja 4 má vontade; inveja dos deuses em rel. aos homens 5 ação de privar de algo por maldade ou inveja; recusa; impedimento: φθόνος οὐδεὶς λέγειν plat. nada impede de dizer.</p></section></article>\n<article id=\"entry-dgp-42517\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φθορά, ᾶς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 311 na letra φ · nº geral 42517</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 destruição; perdição; perda; ruína 2 Fil. dissolução da matéria; fim; morte 3 corrupção; sedução; rapto 4 violência; estupro 5 esmaecimento das cores. 〈φθείρω〉</p></section></article>\n<article id=\"entry-dgp-42518\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φθορεύς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 312 na letra φ · nº geral 42518</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">corruptor; sedutor. 〈φθείρω〉</p></section></article>\n<article id=\"entry-dgp-42519\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φθορή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 313 na letra φ · nº geral 42519</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = φθορά.</p></section></article>\n<article id=\"entry-dgp-42520\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φθορία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 314 na letra φ · nº geral 42520</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ruína; dissolução; destruição. 〈φθόρος〉</p></section></article>\n<article id=\"entry-dgp-42521\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φθόριος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 315 na letra φ · nº geral 42521</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 próprio para destruir; abortivo ♦ τὸ φθόριον 2 droga abortiva. 〈φθορά〉</p></section></article>\n<article id=\"entry-dgp-42522\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φθοροποιός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 316 na letra φ · nº geral 42522</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que corrompe ou destrói; pernicioso; letal 2 abortivo. 〈φθορά, ποιέω〉</p></section></article>\n<article id=\"entry-dgp-42523\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φθόρος, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 317 na letra φ · nº geral 42523</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(ὁ) 1 destruição; perdição; desgraça; fórmula de imprecação, ἐς φθόρον ésql. vai para o inferno! dane-se! 2 flagelo; ser funesto, ref. a pessoa 3 desastre na guerra. 〈φθείρω〉</p></section></article>\n<article id=\"entry-dgp-42524\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φῖ (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 318 na letra φ · nº geral 42524</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fi, letra.</p></section></article>\n<article id=\"entry-dgp-42525\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιάλη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 319 na letra φ · nº geral 42525</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 recipiente para fazer ferver um líquido 2 taça sem pé nem asa; copo (para beber, para libação) 3 urna funerária 4 escudo 5 adorno; ornamento de portas, de tetos.</p></section></article>\n<article id=\"entry-dgp-42526\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιάλλω</h1><div class=\"entry-meta\"><span>DGP · ordem 320 na letra φ · nº geral 42526</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. φιαλῶ) pôr mãos à obra; empreender, dat.</p></section></article>\n<article id=\"entry-dgp-42527\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιδίτιον</h1><div class=\"entry-meta\"><span>DGP · ordem 321 na letra φ · nº geral 42527</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. φειδίτιον.</p></section></article>\n<article id=\"entry-dgp-42528\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλάγαθος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 322 na letra φ · nº geral 42528</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que ama o bem ou as pessoas de bem; que ama a bondade. 〈φίλος, ἀγαθός〉</p></section></article>\n<article id=\"entry-dgp-42529\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φιλαδέλφεια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 323 na letra φ · nº geral 42529</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. Filadélfia, cidade da Ásia.</p></section></article>\n<article id=\"entry-dgp-42530\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλαδελφία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 324 na letra φ · nº geral 42530</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 amizade por irmão ou irmã; amor fraterno 2 crist. amor pelos irmãos; caridade. 〈φιλάδελφος〉</p></section></article>\n<article id=\"entry-dgp-42531\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλάδελφος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 325 na letra φ · nº geral 42531</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que ama seus irmãos e irmãs; fraterno 2 que mostra afeição por um irmão. 〈φίλος, ἀδελφός〉</p></section></article>\n<article id=\"entry-dgp-42532\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλαθήναιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 326 na letra φ · nº geral 42532</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">amigo, partidário dos atenienses. 〈φίλος, Ἀθηναῖος〉</p></section></article>\n<article id=\"entry-dgp-42533\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλαθλητής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 327 na letra φ · nº geral 42533</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">amigo de lutadores ou de lutas. 〈φίλος, ἀθλητής〉</p></section></article>\n<article id=\"entry-dgp-42534\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φίλαθλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 328 na letra φ · nº geral 42534</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que ama as lutas, os jogos. 〈φίλος, ἆθλος〉</p></section></article>\n<article id=\"entry-dgp-42535\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φῖλαι</h1><div class=\"entry-meta\"><span>DGP · ordem 329 na letra φ · nº geral 42535</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª sing. imper. aor. méd. ép. de φιλέω.</p></section></article>\n<article id=\"entry-dgp-42536\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλαίματος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 330 na letra φ · nº geral 42536</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que ama o sangue; sanguinário. 〈φίλος, αἷμα〉</p></section></article>\n<article id=\"entry-dgp-42537\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλαίτατος, φιλαίτερος</h1><div class=\"entry-meta\"><span>DGP · ordem 331 na letra φ · nº geral 42537</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. φίλος.</p></section></article>\n<article id=\"entry-dgp-42538\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλαίτιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 332 na letra φ · nº geral 42538</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que gosta de fazer censuras ou críticas; que gosta de acusar; briguento 2 que gosta de levantar contestações mal fundadas; rábula 3 exposto a críticas, a acusações ♦ τὸ φιλαίτιον 4 mania de fazer censuras; chicanice. 〈φιλία, αἰτία〉</p></section></article>\n<article id=\"entry-dgp-42539\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλαλέξανδρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 333 na letra φ · nº geral 42539</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">admirador ou amigo de Alexan­dre. 〈φίλος, Ἀλέξανδρος〉</p></section></article>\n<article id=\"entry-dgp-42540\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλαλήθης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 334 na letra φ · nº geral 42540</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">amigo da verdade; amante da verdade. 〈φίλος, ἀληθής〉</p></section></article>\n<article id=\"entry-dgp-42541\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλαλήθως</h1><div class=\"entry-meta\"><span>DGP · ordem 335 na letra φ · nº geral 42541</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com amor à verdade; sinceramente; francamente.</p></section></article>\n<article id=\"entry-dgp-42542\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλάλληλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 336 na letra φ · nº geral 42542</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que experimenta afeição mútua, amor recíproco ♦ τὸ φιλάλληλον 2 amor recíproco; afeição mútua. 〈φίλος, ἀλλήλων〉</p></section></article>\n<article id=\"entry-dgp-42543\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλαναγνώστης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 337 na letra φ · nº geral 42543</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) que ama a leitura. 〈φίλος, ἀναγιγνώσκω〉</p></section></article>\n<article id=\"entry-dgp-42544\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φίλανδρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 338 na letra φ · nº geral 42544</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que ama os homens, i.e., seus habitantes (país) 2 que ama os homens viris 3 apaixonado pelos homens 4 bíbl., fem. que ama o esposo. 〈φίλος, ἀνήρ〉</p></section></article>\n<article id=\"entry-dgp-42545\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλανθρώπευμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 339 na letra φ · nº geral 42545</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ato de cortesia, de cordialidade, de humanidade. 〈φιλάνθρωπος〉</p></section></article>\n<article id=\"entry-dgp-42546\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλανθρωπία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 340 na letra φ · nº geral 42546</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sentimento de humanidade; filantropia; bondade; cordialidade; gentileza: φ. λόγων dem. benevolência de linguagem, φιλανθρωπίᾳ xen. por bondade 2 pl. atos de humanidade, de bondade, de cortesia, de gentileza 3 afabilidade; clemência; liberalidade 4 crist. amor pela humanidade 5 atrativo (de coisas) para os homens: χώρα πάσης φιλανθρωπίας ἐστερημένη d.s. região sem qualquer atrativo para os homens. 〈φιλάνθρωπος〉</p></section></article>\n<article id=\"entry-dgp-42547\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλάνθρωπος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 341 na letra φ · nº geral 42547</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 humano; benevolente; afável; filantropo 2 amigo do homem, fiel; obediente (animal) 3 favorável ou útil ao homem; bom; vanjatoso (coisa) 4 que agrada os homens; agradável ♦ τὸ φιλάνθρωπον 5 atrativo para os homens. 〈φίλος, ἄνθρωπος〉</p></section></article>\n<article id=\"entry-dgp-42548\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλανθρώπως</h1><div class=\"entry-meta\"><span>DGP · ordem 342 na letra φ · nº geral 42548</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com humanidade; com bondade.</p></section></article>\n<article id=\"entry-dgp-42549\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλάνωρ</h1><div class=\"entry-meta\"><span>DGP · ordem 343 na letra φ · nº geral 42549</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = φιλήνωρ.</p></section></article>\n<article id=\"entry-dgp-42550\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλαπεχθημόνως</h1><div class=\"entry-meta\"><span>DGP · ordem 344 na letra φ · nº geral 42550</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com maldade.</p></section></article>\n<article id=\"entry-dgp-42551\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλαπεχθημοσύνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 345 na letra φ · nº geral 42551</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">maldade; malignidade. 〈φιλαπεχθήμων〉</p></section></article>\n<article id=\"entry-dgp-42552\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλαπεχθήμων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 346 na letra φ · nº geral 42552</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος que gosta de fazer inimigo; briguento; rancoroso; intratável. 〈φίλος, ἀπεχθ᾽άνομαι〉</p></section></article>\n<article id=\"entry-dgp-42553\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλαπλοϊκός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 347 na letra φ · nº geral 42553</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que ama a simplicidade.</p></section></article>\n<article id=\"entry-dgp-42554\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλαπόδημος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 348 na letra φ · nº geral 42554</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que ama viajar.</p></section></article>\n<article id=\"entry-dgp-42555\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλαργυρία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 349 na letra φ · nº geral 42555</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">amor ao dinheiro; avareza. 〈φιλάργυρος〉</p></section></article>\n<article id=\"entry-dgp-42556\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλάργυρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 350 na letra φ · nº geral 42556</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que ama o dinheiro; avaro.</p></section></article>\n<article id=\"entry-dgp-42557\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλάρχαιος</h1><div class=\"entry-meta\"><span>DGP · ordem 351 na letra φ · nº geral 42557</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e φιλαρχαῖος, ος, ον que ama as antiguidades ou a antiguidade. 〈φίλος, ἀρχαῖος〉</p></section></article>\n<article id=\"entry-dgp-42558\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλαρχέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 352 na letra φ · nº geral 42558</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">amar o poder; ser ambicioso.</p></section></article>\n<article id=\"entry-dgp-42559\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλαρχία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 353 na letra φ · nº geral 42559</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">amor ao poder; ambição. 〈φίλαρχος〉</p></section></article>\n<article id=\"entry-dgp-42560\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φίλαρχος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 354 na letra φ · nº geral 42560</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que ama o poder; ambicioso ♦ τὸ φίλαρχον 2 amor ao poder; ambição. 〈φίλος, ἀρχή〉</p></section></article>\n<article id=\"entry-dgp-42561\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φίλατο</h1><div class=\"entry-meta\"><span>DGP · ordem 355 na letra φ · nº geral 42561</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. aor. méd. poét. de φιλέω.</p></section></article>\n<article id=\"entry-dgp-42562\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φίλαυλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 356 na letra φ · nº geral 42562</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que ama a flauta. 〈φίλος, αὐλός〉</p></section></article>\n<article id=\"entry-dgp-42563\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλαυτία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 357 na letra φ · nº geral 42563</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">amor de si; egoísmo; filáucia. 〈φίλαυτος〉</p></section></article>\n<article id=\"entry-dgp-42564\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φίλαυτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 358 na letra φ · nº geral 42564</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que ama a si mesmo; egoísta ♦ τὸ φίλαυτον 2 amor de si; filáucia. 〈φίλος, αὐτός〉</p></section></article>\n<article id=\"entry-dgp-42565\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλέεσκον</h1><div class=\"entry-meta\"><span>DGP · ordem 359 na letra φ · nº geral 42565</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">impf. iter. de φιλέω.</p></section></article>\n<article id=\"entry-dgp-42566\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλέῃσι</h1><div class=\"entry-meta\"><span>DGP · ordem 360 na letra φ · nº geral 42566</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. pres. subj. ép. de φιλέω.</p></section></article>\n<article id=\"entry-dgp-42567\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλελεύθερος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 361 na letra φ · nº geral 42567</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que ama a liberdade; liberal.</p></section></article>\n<article id=\"entry-dgp-42568\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλέλλην, ηνος</h1><div class=\"entry-meta\"><span>DGP · ordem 362 na letra φ · nº geral 42568</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) amigo ou admirador dos gregos ou das coisas gregas. 〈φίλος, Ἕλλην〉</p></section></article>\n<article id=\"entry-dgp-42569\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλεπιτιμητής, οῦ</h1><div class=\"entry-meta\"><span>DGP · ordem 363 na letra φ · nº geral 42569</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) que gosta de criticar, de censurar.</p></section></article>\n<article id=\"entry-dgp-42570\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλεραστής, οῦ</h1><div class=\"entry-meta\"><span>DGP · ordem 364 na letra φ · nº geral 42570</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) que gosta de amante ou que gosta de ter amantes.</p></section></article>\n<article id=\"entry-dgp-42571\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλεργέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 365 na letra φ · nº geral 42571</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">amar o trabalho; ser trabalhador. 〈φιλεργός〉</p></section></article>\n<article id=\"entry-dgp-42572\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλεργία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 366 na letra φ · nº geral 42572</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">amor ao trabalho; diligência. 〈φιλεργός〉</p></section></article>\n<article id=\"entry-dgp-42573\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλεργός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 367 na letra φ · nº geral 42573</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que ama o trabalho; trabalhador; diligente ♦ τὸ φιλεργόν 2 amor ao trabalho. 〈φίλος, ἔργον〉</p></section></article>\n<article id=\"entry-dgp-42574\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλεργῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 368 na letra φ · nº geral 42574</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. laboriosamente.</p></section></article>\n<article id=\"entry-dgp-42575\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλεταιρία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 369 na letra φ · nº geral 42575</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">afeição pelos companheiros. 〈φιλέταιρος〉</p></section></article>\n<article id=\"entry-dgp-42576\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλέταιρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 370 na letra φ · nº geral 42576</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 afeiçoado aos companheiros ou aos amigos ♦ τὸ φιλέταιρον 2 φιλεταιρία. 〈φίλος, ἑταῖρος〉</p></section></article>\n<article id=\"entry-dgp-42577\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλεῦντας</h1><div class=\"entry-meta\"><span>DGP · ordem 371 na letra φ · nº geral 42577</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ac. pl. masc. part. pres. dór. de φιλέω.</p></section></article>\n<article id=\"entry-dgp-42578\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλευριπίδης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 372 na letra φ · nº geral 42578</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">amigo de Eurípides.</p></section></article>\n<article id=\"entry-dgp-42579\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 373 na letra φ · nº geral 42579</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. φιλήσω, aor. ἐφιλησα, perf. πεφίληκα) 1 amar com amizade (op. a ἐρᾶν); ter amizade; querer bem; estimar alguém, ac., por algo, ἐπί ou ἐν e dat.: φιλεῖν τινα φιλότητα hom. amar alguém com amizade, φ. ἐκ θυμοῦ, θυμῷ, κῆρι, περὶ κῆρι, κηρόθι hom. amar do fundo do coração 2 cuidar de; ajudar; assistir alguém, ac. 3 dar um beijo (em sinal de amizade); beijar: φ. τῷ στόματι her., τοῖς στόμασι xen., κατὰ τὸ στόμα a.p. beijar na boca 4 amar eroticamente 5 colher com prazer; tratar com afeto (hóspede) 6 aprovar; aceitar: φ. σχέτλια ἔργα hom. tolerar más ações 7 procurar obter; perseguir: φ. τὸ κέρδος plat., τὸ κερδαίνειν sóf. correr atrás do lucro 8 comprazer-se com, ac. 9 ter o costume de; apreciar; gostar de, inf. ou part.: φιλεῖ τίκτειν ὕβρις ὕβριν ésql. a violência costuma gerar violência, φιλέει ὁ θεὸς τὰ ὑπερέχον­τα κολούειν her. a divindade aprecia humilhar o que se eleva demais, φιλεῖς δὲ δρωσ᾽ αὐτό ar. gostas de fazer isso οἶα φιλεῖ γίγνεσθαι tuc. como sói acontecer, οἷα φιλεῖ plat. como acontece habitualmente 10 impes. φιλέει, inf. é costume que. ♦ méd. 11 beijar-se mutuamente. 〈φίλος〉</p></section></article>\n<article id=\"entry-dgp-42580\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φίλη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 374 na letra φ · nº geral 42580</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. φίλος.</p></section></article>\n<article id=\"entry-dgp-42581\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιληδέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 375 na letra φ · nº geral 42581</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 encontrar prazer em; deliciar-se com, dat. 2 ter prazer em, part. 〈φιληδής〉</p></section></article>\n<article id=\"entry-dgp-42582\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιληδής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 376 na letra φ · nº geral 42582</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que busca o prazer. 〈φίλος, ἡδύς〉</p></section></article>\n<article id=\"entry-dgp-42583\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιληδία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 377 na letra φ · nº geral 42583</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">prazer; deleite. 〈φιληδής〉</p></section></article>\n<article id=\"entry-dgp-42584\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιληδονέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 378 na letra φ · nº geral 42584</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">φιληδέω.</p></section></article>\n<article id=\"entry-dgp-42585\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιληδονία (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 379 na letra φ · nº geral 42585</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gosto pelo prazer. 〈φιλήδονος〉</p></section></article>\n<article id=\"entry-dgp-42586\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλήδονος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 380 na letra φ · nº geral 42586</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que ama ou procura o prazer; voluptuoso ♦ τὸ φιλήδονον 2 gosto pelo prazer. 〈φίλος, ἡδονή〉</p></section></article>\n<article id=\"entry-dgp-42587\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιληκοία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 381 na letra φ · nº geral 42587</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">prazer em escutar; atenção. 〈φιλήκοος〉</p></section></article>\n<article id=\"entry-dgp-42588\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλήκοος, οος, οον</h1><div class=\"entry-meta\"><span>DGP · ordem 382 na letra φ · nº geral 42588</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que escuta com prazer ou com atenção; ávido por escutar; que gosta de ouvir conversa 2 disposto a escutar ♦ τὸ φιλήκοον 3 gosto de ouvir por mero passatempo. 〈φίλος, ἀκούω〉</p></section></article>\n<article id=\"entry-dgp-42589\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιληλιαστής, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 383 na letra φ · nº geral 42589</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) que gosta de ser heliasta. 〈φίλος, ἡλιαστής〉</p></section></article>\n<article id=\"entry-dgp-42590\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φίλημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 384 na letra φ · nº geral 42590</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">beijo. 〈φιλέω〉</p></section></article>\n<article id=\"entry-dgp-42591\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλήμεναι</h1><div class=\"entry-meta\"><span>DGP · ordem 385 na letra φ · nº geral 42591</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. pres. ép. de φιλέω.</p></section></article>\n<article id=\"entry-dgp-42592\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλήμων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 386 na letra φ · nº geral 42592</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος 1 afável ♦ ὁ Φιλήμων 2 Filemão, n. de h. 〈φιλέω〉</p></section></article>\n<article id=\"entry-dgp-42593\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλήνεμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 387 na letra φ · nº geral 42593</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que ama o vento; exposto ao vento; ventoso. 〈φίλος, ἄνεμος〉</p></section></article>\n<article id=\"entry-dgp-42594\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλήνιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 388 na letra φ · nº geral 42594</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que aceita o freio; dócil. 〈φίλος, ἡνία〉</p></section></article>\n<article id=\"entry-dgp-42595\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλήνωρ, ορος</h1><div class=\"entry-meta\"><span>DGP · ordem 389 na letra φ · nº geral 42595</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) conjugal. 〈φίλος, ἀνήρ〉</p></section></article>\n<article id=\"entry-dgp-42596\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιληρέτμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 390 na letra φ · nº geral 42596</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que ama o remo. 〈φίλος, ἐρετμός〉</p></section></article>\n<article id=\"entry-dgp-42597\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλησέμεν</h1><div class=\"entry-meta\"><span>DGP · ordem 391 na letra φ · nº geral 42597</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. fut. ép. de φιλέω.</p></section></article>\n<article id=\"entry-dgp-42598\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φίλησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 392 na letra φ · nº geral 42598</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">estima; afeição. 〈φιλέω〉</p></section></article>\n<article id=\"entry-dgp-42599\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλητέον</h1><div class=\"entry-meta\"><span>DGP · ordem 393 na letra φ · nº geral 42599</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de φιλέω.</p></section></article>\n<article id=\"entry-dgp-42600\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φίλητος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 394 na letra φ · nº geral 42600</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. Fileto, n. de h.</p></section></article>\n";
